steps.action:
curl -s https://api.linear.app/graphql \
  -X POST \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams(name: \"Web Platform\") {
          nodes {
            id
            name
            issues(filter: {
              assignee: { name: { eq: \"Priya Nair\" } },
              state: { name: { contains: \"Cycle 4\" } }
            }) {
              nodes {
                id
                title
                description
                priority
                assignee {
                  name
                }
                state {
                  name
                }
              }
            }
          }
        }
      }
    "
  }'
